// The framework list, port ranges, languages and report schemas, generated by build.rs from
// config/config.go and benchcli-go/report/*.go with benchcli-uwscpp/generate_metadata.py:
//
//   ports         framework -> [first, last]
//   frameworks    config.FrameworkList, in order
//   langs         framework -> its server's language, the Lang column
//   schemas       report kind -> its fields in declaration order, each with key (the JSON
//                 name), title (the md tag), fmt, optional (tpn), hidden (md:"-"), rank,
//                 summary, string and floating
//   summaryOrder  report.SummaryParameters: name and description
use std::sync::LazyLock;

use serde_json::Value;

static METADATA: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!(concat!(env!("OUT_DIR"), "/metadata.json")))
        .expect("metadata.json generated by build.rs")
});

pub fn metadata() -> &'static Value {
    &METADATA
}

pub fn ports(framework: &str) -> (u16, u16) {
    let range = &metadata()["ports"][framework];
    (
        range[0].as_u64().unwrap() as u16,
        range[1].as_u64().unwrap() as u16,
    )
}

pub fn frameworks() -> impl Iterator<Item = &'static str> {
    metadata()["frameworks"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| f.as_str().unwrap())
}

// The language a framework's server is written in, as config.FrameworkLang has it.
pub fn lang(framework: &str) -> &'static str {
    metadata()["langs"][framework].as_str().unwrap_or("-")
}

pub fn schema(kind: &str) -> &'static [Value] {
    metadata()["schemas"][kind].as_array().unwrap()
}

pub fn summary_order() -> &'static [Value] {
    metadata()["summaryOrder"].as_array().unwrap()
}
